import sys
import heapq

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def dijkstra(graph, start):
    n = len(graph)
    dist = [float('inf')] * n
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

def main():
    n, m = read_ints()
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        v, u = read_ints()
        graph[v].append((u, 1))
        graph[u].append((v, 1))

    dist_from_1 = dijkstra(graph, 1)
    dist_from_n = dijkstra(graph, n)

    max_avg = 0.0
    best_city = 1
    for i in range(1, n + 1):
        safe_roads = 0
        for j in range(1, n + 1):
            for v, w in graph[j]:
                if dist_from_1[j] + w == dist_from_1[v] and dist_from_n[j] + w == dist_from_n[v]:
                    safe_roads += 1
        avg_safe_roads = safe_roads / (n - 1)
        if avg_safe_roads > max_avg:
            max_avg = avg_safe_roads
            best_city = i

    print("{:.12f}".format(max_avg))

if __name__ == "__main__":
    main()
